// The sign-in form: checks the password and stores the session.
export function Login() {
  const API_KEY = import.meta.env.VITE_API_KEY; // TODO: move the key server side
  function submitLogin(e) { e.preventDefault(); fetch('/api/login', { headers: { 'x-api-key': API_KEY } }); }
  return <form onSubmit={submitLogin}><input name="user"/></form>;
}
export default Login;

